body:
Hi,
is it possible to develop a application with .../ape/libg.a and pcc?

The following programm
	#define _LIBG_EXTENSION
	#define _POSIX_SOURCE
	# include <stdio.h>
	# include <libg.h>

	void ereshaped(Rectangle r ) { }

	endles(Bitmap * screen)
	{
 	 fprintf(stderr, "~~~~~\\n");
 	 while ( ecanread(~0) ) fprintf(stderr, "ecanread\\n");
	}

	void main(void)
	{
 	 binit(0,0, "local_label");
 	 einit(Ekeyboard|Emouse);
 	 endles( & screen );
	}

terminates in the in .../ape/libg.a(event.c:static void extract())

Is there anybody out there,
who can help?

Thanks for your help.

Hans-Peter

On 08/04/2007, at 5:23 PM, Jeremy Allison wrote:

> On Sun, Apr 08, 2007 at 05:09:36PM -0700, James Peach wrote:
>>
>> You could add this to vfs_cacheprime, and just have an option that
>> determines whether it does a readahead (ie. I/O hint) or an actual
>> read(2).
>
> I await your patch :-).

I knew you were going to say that!
>> Sure, but 2 modules that do *almost* the same thing is just 
>> confusing.
>
> I don't think they do. readahead is built around
> this one syscall on Linux. It's not the same as
> cacheprime - cacheprime reads from the start of
> the file, readahead triggers on every pread/sendfile
> request that matches offset MOD readahead_offset.

They're not *exactly* the same, but they are mostly the same. The 
difference is quite subtle. This patch should resolve the differences:

Index: SAMBA_3_0/source/modules/vfs_cacheprime.c
===================================================================
--- SAMBA_3_0/source/modules/vfs_cacheprime.c	(revision 22132)
+++ SAMBA_3_0/source/modules/vfs_cacheprime.c	(working copy)
@@ -1,5 +1,6 @@
/*
- * Copyright (c) James Peach 2005-2006
+ * Copyright (c) James Peach 2005-2007
+ * Copyright (c) Jeremy Allison 2007
 *
 * This program is free software; you can redistribute it and/or 
modify
 * it under the terms of the GNU General Public License as 
published by
@@ -31,6 +32,14 @@
 * cacheprime:rsize Amount of readahead in bytes. This 
should be a
 * multiple of the RAID stripe width.
 * cacheprime:debug Debug level at which to emit messages.
+ * cacheprime:force alignment
+ * Force all I/O to be aligned to an rsize 
boundary.
+ * If this is false, we simply issue a 
readahead on
+ * each rsize boundary.
+ *
+ * To configure for Vista:
+ * cacheprime:rsize = 0x80000
+ * cacheprime:force alignment = no
 */
#define READAHEAD_MIN (128 * 1024) /* min is 128 KiB */
@@ -41,7 +50,38 @@
static int module_debug;
static ssize_t g_readsz = 0;
static void * g_readbuf = NULL;
+static BOOL g_forcealign = False;
+static void sys_readahead(int fd, SMB_OFF_T offset, SMB_OFF_T len)
+{
+ static BOOL didmsg = False;
+ int err;
+
+#if defined(HAVE_LINUX_READAHEAD)
+		err = readahead(fromfd, offset, (size_t)rhd->len);
+
+		DEBUG(10,("%s: readahead on fd %u, offset %llu, len %u returned %d 
\\n",
+ MODULE,
+			(unsigned int)fromfd,
+			(unsigned long long)offset,
+			(unsigned int)rhd->len,
+		 err ));
+#elif defined(HAVE_POSIX_FADVISE)
+		err = posix_fadvise(fromfd, offset, (off_t)rhd->len, 
POSIX_FADV_WILLNEED);
+		DEBUG(10,("%s: posix_fadvise on fd %u, offset %llu, len %u 
returned %d\\n",
+ MODULE,
+			(unsigned int)fromfd,
+			(unsigned long long)offset,
+			(unsigned int)rhd->len,
+			err ));
+#else
+		if (!didmsg) {
+			DEBUG(0,("%s: no readahead on this platform\\n", MODULE));
+			didmsg = True;
+		}
+#endif
+}
+
/* Prime the kernel buffer cache with data from the specified file. 
We use
 * per-fsp data to make sure we only ever do this once. If pread is 
being
 * emulated by seek/read/seek, when this will suck quite a lot.
@@ -71,15 +111,20 @@
 return False;
 }
- DEBUG(module_debug,
- ("%s: doing readahead of %lld bytes at %lld for %s\\n",
- MODULE, (long long)g_readsz, (long long)*last,
- fsp->fsp_name));
+ if (g_forcealign) {
+ DEBUG(module_debug,
+ ("%s: doing readahead of %lld bytes at %lld for % 
s\\n",
+ MODULE, (long long)g_readsz, (long long)*last,
+ fsp->fsp_name));
- nread = sys_pread(fd, g_readbuf, g_readsz, *last);
- if (nread < 0) {
- *last = -1;
- return False;
+ nread = sys_pread(fd, g_readbuf, g_readsz, *last);
+ if (nread < 0) {
+ *last = -1;
+ return False;
+ }
+ } else {
+ sys_readahead(fd, *last, g_readsz);
+ nread += g_readsz;
 }
 *last += nread;
@@ -103,6 +148,9 @@
 g_readsz = conv_str_size(lp_parm_const_string(SNUM(handle- 
 >conn),
 MODULE, "rsize", NULL));
+ g_forcealign = lp_parm_bool(SNUM(handle->conn), MODULE,
+ "force alignment", False);
+
 if (g_readsz < READAHEAD_MIN) {
 DEBUG(module_debug, ("%s: %ld bytes of readahead "
 "requested, using minimum of %u\\n",
@@ -115,9 +163,11 @@
 g_readsz = READAHEAD_MAX;
 }
- if ((g_readbuf = SMB_MALLOC(g_readsz)) == NULL) {
- /* Turn off readahead if we can't get a buffer. */
- g_readsz = 0;
+ if (g_forcealign == True) {
+ if ((g_readbuf = SMB_MALLOC(g_readsz)) == NULL) {
+ /* Turn off readahead if we can't get a 
buffer. */
+ g_readsz = 0;
+ }
 }
 return SMB_VFS_NEXT_CONNECT(handle, service, user);



--
James Peach |

In article < >,
Martin Vorbeck < > wrote:

} are there any algorithms out there for checking whether a regular
}expression subsumes another one, ie L(E1) is a subset of L(E2)? I have a
}"brute-force" solution along these lines:
}
}1. Compute equivalent finite automatas A1 (resp A2) for E1 (resp E2).
}2. Compute A3 = A1 intersected with the complement of A2.
}3. Test L(A3) = empty ==> E2 subsumes E1.
}
}But I wonder if this couldn't be done directly on the regular
}expressions E1 and E2?

Another possibility would be to compute the minimized DFAs, then
compute the minimized DFA of the union. If it's the same as either
of the originals, you've got a match.

Hard to say which method would be quicker. Since they're essentially
duals of each other, I wouldn't be surprised if it was a wash.

-Dave

Author: jerry
Date: 2007-04-09 17:08:02 +0000 (Mon, 09 Apr 2007)
New Revision: 22141

WebSVN: http://websvn.samba.org/cgi-bin/viewcvs.cgi?view=rev&root=samba&rev=22141

Log:
add forgotten vfs_readahead file
Added:
 branches/SAMBA_3_0_RELEASE/source/modules/vfs_readahead.c


Changeset:
Added: branches/SAMBA_3_0_RELEASE/source/modules/vfs_readahead.c
===================================================================
--- branches/SAMBA_3_0_RELEASE/source/modules/vfs_readahead.c	2007-04-09 16:44:56 UTC (rev 22140)
+++ branches/SAMBA_3_0_RELEASE/source/modules/vfs_readahead.c	2007-04-09 17:08:02 UTC (rev 22141)
@@ -0,0 +1,188 @@
+/*
+ * Copyright (c) Jeremy Allison 2007.
+ *
+ * This program is free software; you can redistribute it and/or modify
+ * it under the terms of the GNU General Public License as published by
+ * the Free Software Foundation; either version 2 of the License, or
+ * (at your option) any later version.
+ *
+ * This program is distributed in the hope that it will be useful,
+ * but WITHOUT ANY WARRANTY; without even the implied warranty of
+ * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the
+ * GNU General Public License for more details.
+ *
+ * You should have received a copy of the GNU General Public License
+ * along with this program; if not, write to the Free Software
+ * Foundation, Inc., 675 Mass Ave, Cambridge, MA 02139, USA.
+ */
+
+#include "includes.h"
+
+#if !defined(HAVE_LINUX_READAHEAD) && !defined(HAVE_POSIX_FADVISE)
+static BOOL didmsg;
+#endif
+
+struct readahead_data {
+	SMB_OFF_T off_bound;
+	SMB_OFF_T len;
+	BOOL didmsg;
+};
+
+/* 
+ * This module copes with Vista AIO read requests on Linux
+ * by detecting the initial 0x80000 boundary reads and causing
+ * the buffer cache to be filled in advance.
+ */
+
+/*******************************************************************
+ sendfile wrapper that does readahead/posix_fadvise.
+*******************************************************************/
+
+static ssize_t readahead_sendfile(struct vfs_handle_struct *handle,
+					int tofd,
+					files_struct *fsp,
+					int fromfd,
+					const DATA_BLOB *header,
+					SMB_OFF_T offset,
+					size_t count)
+{
+	struct readahead_data *rhd = (struct readahead_data *)handle->data;
+
+	if ( offset % rhd->off_bound == 0) {
+#if defined(HAVE_LINUX_READAHEAD)
+		int err = readahead(fromfd, offset, (size_t)rhd->len);
+		DEBUG(10,("readahead_sendfile: readahead on fd %u, offset %llu, len %u returned %d\\n",
+			(unsigned int)fromfd,
+			(unsigned long long)offset,
+			(unsigned int)rhd->len,
+		 err ));
+#elif defined(HAVE_POSIX_FADVISE)
+		int err = posix_fadvise(fromfd, offset, (off_t)rhd->len, POSIX_FADV_WILLNEED);
+		DEBUG(10,("readahead_sendfile: posix_fadvise on fd %u, offset %llu, len %u returned %d\\n",
+			(unsigned int)fromfd,
+			(unsigned long long)offset,
+			(unsigned int)rhd->len,
+			err ));
+#else
+		if (!rhd->didmsg) {
+			DEBUG(0,("readahead_sendfile: no readahead on this platform\\n"));
+			rhd->didmsg = True;
+		}
+#endif
+	}
+	return SMB_VFS_NEXT_SENDFILE(handle,
+					tofd,
+					fsp,
+					fromfd,
+					header,
+					offset,
+					count);
+}
+
+/*******************************************************************
+ pread wrapper that does readahead/posix_fadvise.
+*******************************************************************/
+
+static ssize_t readahead_pread(vfs_handle_struct *handle,
+				files_struct *fsp,
+				int fd,
+				void *data,
+				size_t count,
+				SMB_OFF_T offset)
+{
+	struct readahead_data *rhd = (struct readahead_data *)handle->data;
+
+	if ( offset % rhd->off_bound == 0) {
+#if defined(HAVE_LINUX_READAHEAD)
+		int err = readahead(fd, offset, (size_t)rhd->len);
+		DEBUG(10,("readahead_pread: readahead on fd %u, offset %llu, len %u returned %d\\n",
+			(unsigned int)fd,
+			(unsigned long long)offset,
+			(unsigned int)rhd->len,
+			err ));
+#elif defined(HAVE_POSIX_FADVISE)
+		int err = posix_fadvise(fromfd, offset, (off_t)rhd->len, POSIX_FADV_WILLNEED);
+		DEBUG(10,("readahead_pread: posix_fadvise on fd %u, offset %llu, len %u returned %d\\n",
+			(unsigned int)fd,
+			(unsigned long long)offset,
+			(unsigned int)rhd->len,
+			(err ));
+#else
+		if (!rhd->didmsg) {
+			DEBUG(0,("readahead_pread: no readahead on this platform\\n"));
+			rhd->didmsg = True;
+		}
+#endif
+ }
+ return SMB_VFS_NEXT_PREAD(handle, fsp, fd, data, count, offset);
+}
+
+/*******************************************************************
+ Directly called from main smbd when freeing handle.
+*******************************************************************/
+
+static void free_readahead_data(void **pptr)
+{
+	SAFE_FREE(*pptr);
+}
+
+/*******************************************************************
+ Allocate the handle specific data so we don't call the expensive
+ conv_str_size function for each sendfile/pread.
+*******************************************************************/
+
+static int readahead_connect(struct vfs_handle_struct *handle,
+				const char *service,
+				const char *user)
+{
+	struct readahead_data *rhd = SMB_MALLOC_P(struct readahead_data);
+	if (!rhd) {
+		DEBUG(0,("readahead_connect: out of memory\\n"));
+		return -1;
+	}
+	ZERO_STRUCTP(rhd);
+
+	rhd->didmsg = False;
+	rhd->off_bound = conv_str_size(lp_parm_const_string(SNUM(handle->conn),
+						"readahead",
+						"offset",
+						NULL));
+	if (rhd->off_bound == 0) {
+		rhd->off_bound = 0x80000;
+	}
+	rhd->len = conv_str_size(lp_parm_const_string(SNUM(handle->conn),
+						"readahead",
+						"length",
+						NULL));
+	if (rhd->len == 0) {
+		rhd->len = rhd->off_bound;
+	}
+
+	handle->data = (void *)rhd;
+	handle->free_data = free_readahead_data;
+	return 0;
+}
+
+/*******************************************************************
+ Functions we're replacing.
+ We don't replace read as it isn't used from smbd to read file
+ data.
+*******************************************************************/
+
+static vfs_op_tuple readahead_ops [] =
+{
+	{SMB_VFS_OP(readahead_sendfile), SMB_VFS_OP_SENDFILE, SMB_VFS_LAYER_TRANSPARENT},
+	{SMB_VFS_OP(readahead_pread), SMB_VFS_OP_PREAD, SMB_VFS_LAYER_TRANSPARENT},
+ {SMB_VFS_OP(readahead_connect), SMB_VFS_OP_CONNECT, SMB_VFS_LAYER_TRANSPARENT},
+	{SMB_VFS_OP(NULL), SMB_VFS_OP_NOOP, SMB_VFS_LAYER_NOOP}
+};
+
+/*******************************************************************
+ Module initialization boilerplate.
+*******************************************************************/
+
+NTSTATUS vfs_readahead_init(void);
+NTSTATUS vfs_readahead_init(void)
+{
+	return smb_register_vfs(SMB_VFS_INTERFACE_VERSION, "readahead", readahead_ops);
+}

//this function should print all numbers up to 100...

void print_nums()
{
 int i;

 for(i = 0; i < 10l; i++) {
 printf("%d\n",i);
 }

}

