#############################################

#!/usr/bin/perl

use CGI qw(:all);
use CGI::Carp qw(fatalsToBrowser);

my $message = "";

foreach my $param (param())
{
 my $value = param($param);
 $message .= "param \\"$param\\" = \\"$value\\" ";
}

my $program_name = __FILE__;
$program_name =~ s/^.*\\///; # remove all path, leaving only actual
program name

my $checkbox = "
 checkbox name = \\"sitelist\\" (same for each option) 

Arlington 
 Houston

 Plano 

 checkbox name changes with each option 

Arlington 
 Houston 
 Plano 

";

# begin displaying web page
print header("text/html");
print start_html();
print start_form();

print " $message ";

print " $checkbox ";

print end_form();
print end_html;

